 25 | use serde_json::Value;
 26 | 
 27 | use crate::error::{SessionError, SessionResult};
 28 | use crate::session::session::Session;
 29 | use crate::session::types::{Entry, EntryOrder, EntryQuery};
 30 | 
 31 | /// The reserved `customType` that marks a session value entry.
 32 | pub const VALUE_CUSTOM_TYPE: &str = "ice.value";
 33 | 
 34 | /// A loaded, latest-wins view of the session's values. Cheap to clone.
 35 | #[derive(Debug, Clone, Default, PartialEq)]
 36 | pub struct SessionValues {
 37 |     values: BTreeMap<String, Value>,
 38 | }
 39 | 
 40 | impl SessionValues {
 41 |     /// Load every value from the session, resolving latest-wins and dropping
 42 |     /// tombstoned keys.
 43 |     pub async fn load(session: &Session) -> SessionResult<Self> {
 44 |         let entries = session
 45 |             .find_entries(&EntryQuery {
 46 |                 entry_type: Some("custom"),
 47 |                 custom_type: Some(VALUE_CUSTOM_TYPE.to_string()),
 48 |                 order: Some(EntryOrder::OldestFirst),
 49 |                 limit: None,
 50 |                 cursor: None,
 51 |             })
 52 |             .await?;
 53 |         Ok(Self::from_entries(&entries))
 54 |     }
 55 | 
 56 |     /// Resolve a value set from already-fetched entries (oldest first).
 57 |     pub fn from_entries(entries: &[Entry]) -> Self {
 58 |         let mut values = BTreeMap::new();
 59 |         for entry in entries {
 60 |             let Entry::Custom(custom) = entry else {
 61 |                 continue;
 62 |             };
 63 |             if custom.custom_type != VALUE_CUSTOM_TYPE {
 64 |                 continue;
 65 |             }
 66 |             let Some(data) = &custom.data else {
 67 |                 continue;
 68 |             };
 69 |             let Some(key) = data.get("key").and_then(Value::as_str) else {
 70 |                 continue;
 71 |             };
 72 |             match data.get("value") {
 73 |                 // Tombstone: delete from this point forward.
 74 |                 Some(Value::Null) | None => {
 75 |                     values.remove(key);
 76 |                 }
 77 |                 Some(value) => {
 78 |                     values.insert(key.to_string(), value.clone());
 79 |                 }
 80 |             }
 81 |         }
 82 |         Self { values }
 83 |     }
 84 | 
 85 |     /// Read a value.
 86 |     pub fn get(&self, key: &str) -> Option<&Value> {
 87 |         self.values.get(key)
 88 |     }
 89 | 
 90 |     /// Read a typed value, returning `None` when absent or the wrong shape.
 91 |     pub fn get_as<T: serde::de::DeserializeOwned>(&self, key: &str) -> Option<T> {
 92 |         let value = self.values.get(key)?;
 93 |         serde_json::from_value(value.clone()).ok()
 94 |     }
 95 | 
 96 |     /// Every live key/value pair, ordered by key.
 97 |     pub fn iter(&self) -> impl Iterator<Item = (&str, &Value)> {
 98 |         self.values.iter().map(|(k, v)| (k.as_str(), v))
 99 |     }
100 | 
101 |     /// The number of live keys.
102 |     pub fn len(&self) -> usize {
103 |         self.values.len()
104 |     }
105 | 
106 |     /// Whether there are no live keys.
107 |     pub fn is_empty(&self) -> bool {
108 |         self.values.is_empty()
109 |     }
110 | }
111 | 
112 | /// Durable writer for session values. Each write appends one custom entry, so
113 | /// the operation is crash-safe and ordering-preserving.
114 | #[derive(Clone)]
115 | pub struct SessionValueWriter {
116 |     session: Session,
117 | }
118 | 
119 | impl SessionValueWriter {
120 |     pub fn new(session: Session) -> Self {
121 |         Self { session }
122 |     }
123 | 
124 |     /// `setValue(key, value)` — persist a value (latest-wins).
125 |     pub async fn set(&self, key: &str, value: Value) -> SessionResult<String> {
126 |         self.append(key, Some(value)).await
127 |     }
128 | 
129 |     /// `deleteValue(key)` — persist a tombstone.
130 |     pub async fn delete(&self, key: &str) -> SessionResult<String> {
131 |         self.append(key, None).await
132 |     }
133 | 
134 |     async fn append(&self, key: &str, value: Option<Value>) -> SessionResult<String> {
135 |         if key.trim().is_empty() {
136 |             return Err(SessionError::invalid_payload(
137 |                 "session value key must not be empty",
138 |             ));
139 |         }
140 |         let data = serde_json::json!({
141 |             "key": key,
142 |             "value": value.unwrap_or(Value::Null),
143 |         });
144 |         self.session
145 |             .append_custom_entry(VALUE_CUSTOM_TYPE, Some(data))
146 |             .await
147 |     }
148 | }

